19	const PROCESSING_FEE = 5;
20	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number | undefined> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
32	
33	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
34	const COMPONENT_BLOCK_SIZE = 3;
35	const COMPONENT_BLOCK_PREMIUM = 60;
36	
37	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
38	
39	const countByType = (items: Item[]): Map<string, number> => {
40	  const counts = new Map<string, number>();
41	  for (const item of items) {
42	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
43	  }
44	  return counts;
45	};
46	
47	/**
48	 * Components of one type form a "building block" only when there are exactly 3
49	 * of them; otherwise each is priced individually.
50	 */
51	const componentGroupPremium = (type: string, count: number): number =>
52	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * (BASE_PREMIUMS[type] ?? 0);
53	
54	const policyBasePremiumOf = (step: QuoteStep): number => {
55	  const components = step.items.filter(isComponent);
56	  const mainItems = step.items.filter((item) => !isComponent(item));
57	
58	  let total = mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0);
59	  for (const [type, count] of countByType(components)) {
60	    total += componentGroupPremium(type, count);
61	  }
62	  return total;
63	};
64	
65	/** Kept as an exact fraction — only the final premium is rounded. */
66	const premiumBeforeRounding = (step: QuoteStep): number => {
67	  const policyBasePremium = policyBasePremiumOf(step);
68	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
69	  return policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE;
70	};
71	
72	/** Rounded up, in the MHPCO's favour. */
73	const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));
74	
75	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
76	  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
77	});
