/** Splits items into the ones priced as type groups and the ones priced individually. */
const partitionComponents = (items: Item[]): { components: Item[]; mainItems: Item[] } => {
  const components: Item[] = [];
  const mainItems: Item[] = [];
  for (const item of items) {
    (isComponent(item) ? components : mainItems).push(item);
  }
  return { components, mainItems };
};

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/**
 * Components of one type form a "building block" only when there are exactly 3
 * of them; otherwise each is priced individually.
 */
const componentGroupPremium = (type: string, count: number): number =>
  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * basePremiumOf({ type });

const policyBasePremiumOf = (step: QuoteStep): number => {
  const { components, mainItems } = partitionComponents(step.items);

  const mainItemsPremium = mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0);
  const componentsPremium = [...countByType(components)].reduce(
    (sum, [type, count]) => sum + componentGroupPremium(type, count),
    0,
  );
  return mainItemsPremium + componentsPremium;
};
